const b = $('Webhook Tutory').first().json.body || {};
const EVENTOS_PEDIDO = ['pix_gerado','boleto_gerado','pagamento_aprovado','pagamento_recusado','pagamento_cancelado'];
if (EVENTOS_PEDIDO.indexOf(b.evento) === -1) return [];

const MAPA_STATUS = { pending: 'pending', paid: 'paid', failed: 'failed', canceled: 'canceled' };
const status = MAPA_STATUS[String(b.status || '').toLowerCase()] || String(b.status || b.evento || '');

const nome = String(b.nome || '').trim();
const partes = nome.split(/\s+/);
const pn = partes.shift() || '';
const sn = partes.join(' ');

let tel = String(b.telefone || '').replace(/\D/g, '').replace(/^0+/, '');
if (tel) {
  if (tel.indexOf('55') === 0 && (tel.length === 12 || tel.length === 13)) {}
  else if (tel.length === 10 || tel.length === 11) tel = '55' + tel;
}

const limpa = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const UF = { 'acre':'AC','alagoas':'AL','amapa':'AP','amazonas':'AM','bahia':'BA','ceara':'CE','distrito federal':'DF','espirito santo':'ES','goias':'GO','maranhao':'MA','mato grosso':'MT','mato grosso do sul':'MS','minas gerais':'MG','para':'PA','paraiba':'PB','parana':'PR','pernambuco':'PE','piaui':'PI','rio de janeiro':'RJ','rio grande do norte':'RN','rio grande do sul':'RS','rondonia':'RO','roraima':'RR','santa catarina':'SC','sao paulo':'SP','sergipe':'SE','tocantins':'TO' };
let estado = String((b.endereco && b.endereco.estado) || '').trim();
if (estado.length === 2) estado = estado.toUpperCase();
else estado = UF[limpa(estado)] || estado.slice(0, 2).toUpperCase();

let valor = b.valor;
if (valor === undefined || valor === null) valor = b.valores && b.valores.bruto;
if (valor === undefined || valor === null) valor = b.oferta && b.oferta.valor;
const liquido = b.valores && b.valores.liquido;

const meta = b.metadados || {};
let utms = meta.utms_json;
if (!utms && typeof meta.utms === 'string') { try { utms = JSON.parse(meta.utms); } catch (e) { utms = {}; } }
utms = utms || {};

let dh = null;
if (Array.isArray(b.cobrancas) && b.cobrancas[0] && b.cobrancas[0].data_pagamento) dh = b.cobrancas[0].data_pagamento;
const agora = DateTime.now().setZone('America/Sao_Paulo');
const dhFinal = dh ? String(dh).replace('T', ' ').slice(0, 19) : agora.toFormat('yyyy-LL-dd HH:mm:ss');

return [{ json: {
  dh: dhFinal,
  id: String(b.id || ''),
  evento: String(b.evento || ''),
  status: status,
  valor: (valor === undefined || valor === null) ? null : Number(valor),
  liquido: (liquido === undefined || liquido === null) ? null : Number(liquido),
  meio: String(b.meio || ''),
  cupom: String(meta.cupom || ''),
  produto: String((b.produto && b.produto.nome) || ''),
  produto_id: String((b.produto && b.produto.id) || ''),
  email: String(b.email || '').toLowerCase(),
  telefone: tel,
  pn: pn, sn: sn,
  estado: estado,
  cidade: String((b.endereco && b.endereco.cidade) || ''),
  us: String(utms.utm_source || ''),
  um: String(utms.utm_medium || ''),
  uc: String(utms.utm_campaign || ''),
  uct: String(utms.utm_content || ''),
  ut: String(utms.utm_term || '')
} }];
